const KR='cc-bk-read',KP='cc-bk-prac',KPASS='cc-bk-pass';
const readSet=()=>new Set(getJ(KR,[])),pracSet=()=>new Set(getJ(KP,[]));
function isRead(id){if(isF(id)){try{return (window.ccSchool&&window.ccSchool.termDone().includes(fNo(id)))||readSet().has(id)}catch(e){return readSet().has(id)}}return readSet().has(id)}
const isPrac=id=>pracSet().has(id);
const lessonDone=id=>isRead(id)&&isPrac(id);
function toggle(key,id,on){const s=new Set(getJ(key,[]));if(on)s.add(id);else s.delete(id);setJ(key,[...s])}
function setRead(id,on){if(isF(id)&&window.ccSchool){const a=window.ccSchool.termDone(),n=fNo(id),k=a.indexOf(n);if(on&&k<0)a.push(n);if(!on&&k>=0)a.splice(k,1);store.set('cc-mts-term',JSON.stringify(a))}toggle(KR,id,on)}
const met=n=>window.ccSchool&&window.ccSchool.met?window.ccSchool.met(n):true;
const NEEDS={chat:'Works with Copilot Chat',lic:'Needs the licence',cw:'Needs Cowork',ab:'Needs agent building'};
const needTag=n=>n?`<span class="mts-need" data-need="${n}"><span class="mts-needd" aria-hidden="true"></span><span>${xe(NEEDS[n])}<span class="mts-needx">: not on for you yet</span></span></span>`:'';
/* which lens: the garden's terms (cc-term) or the Book's (cc-gterm) */
const LENS={garden:{key:'cc-term',terms:G.terms||{},label:'The Mock Turtle\u2019s terms',place:(G.place||{}).garden||[]},glass:{key:'cc-gterm',terms:G.gterms||{},label:'The Looking-Glass Book',place:(G.place||{}).glass||[]}};
