/* ===== v94 (Charlie, 22 Oct 2026): Which door? Chat, Cowork, Code or Autopilot =====
   The most common question people ask, answered in three places from one renderer: a School lesson in the garden (mts-doors),
   a playbook card through the looking-glass (Actions, Playbooks: window.ccDoorsInto), and the first step of the Caterpillar
   and Ask Alice. The four doors, Bill's three-question picker, one program in four shapes of work, and (through the glass)
   the guardrails and spend. Content: window.DOORS in when_data.js. */
(function(){const K=window.ccGK,D=window.DOORS;if(!K||!D)return;
const {PAGES,xe,ic,store}=K;
const ST={now:'Ready now',test:'Being tested',soon:'On its way'};
const door=id=>D.doors.find(d=>d.id===id);
function picker(pre){return `<div class="wd-pick glass" data-wdpick="${pre}"><div class="wd-pickh"><span class="wd-pi" aria-hidden="true">${ic('cater')}</span><div><h4>Which door is yours?</h4><p>Answer up to three questions. ${xe(D.test)}</p></div></div>
 <ol class="wd-qs">${D.qs.map((q,i)=>`<li class="wd-q${i?' wd-wait':''}" data-q="${i}"><span class="wd-qn">${i+1}</span><p>${xe(q.q)}</p><span class="wd-yn"><button type="button" class="btn" data-wdans="yes" data-q="${i}">Yes</button><button type="button" class="btn" data-wdans="no" data-q="${i}">No</button></span></li>`).join('')}</ol>
 <div class="wd-res" aria-live="polite"><p class="wd-hint">Your door appears here.</p></div></div>`}
function result(id){const d=door(id);return `<div class="wd-resc" style="--dc:${d.col}"><span class="wd-ri" aria-hidden="true">${ic(d.ic)}</span><div><div class="k">Your door</div><h4>${xe(d.t)}: ${xe(d.verb.toLowerCase())}</h4><p>${xe(d.gets)}. ${xe(d.starts)}</p><p class="wd-rex"><b>For example:</b> ${xe(d.ex.t)}.</p><span class="wd-rb"><button type="button" class="aglink" data-wdshow="${d.id}">See the example <span aria-hidden="true">&rarr;</span></button><button type="button" class="aglink" data-wdagain="1">Start again</button></span></div></div>`}
function card(d,glass){return `<article class="wd-door" id="wd-${d.id}" style="--dc:${d.col}"><header><span class="wd-di" aria-hidden="true">${ic(d.ic)}</span><div><div class="k">${xe(d.size)}</div><h4>${xe(d.t)} <span>${xe(d.verb)}</span></h4></div><span class="wd-st wd-${d.st}">${xe(ST[d.st]||'')}</span></header>
 <dl><div><dt>Who starts</dt><dd>${xe(d.starts)}</dd></div><div><dt>Runs for</dt><dd>${xe(d.runs)}</dd></div><div><dt>You get</dt><dd>${xe(d.gets)}</dd></div><div><dt>Sign-off</dt><dd>${xe(d.sign)}</dd></div>${glass?`<div><dt>Billing</dt><dd>${xe(d.bill)}</dd></div><div><dt>Availability</dt><dd>${xe(d.avail)}</dd></div>`:''}</dl>
 <details class="wd-ex"><summary><b>Example:</b> ${xe(d.ex.t)}</summary><p class="wd-m">${xe(d.ex.m)}</p><div class="wd-code"><div class="wd-codeh"><span>${d.id==='autopilot'?'The goal it is given':'The prompt'}</span><button type="button" class="mts-copy" data-wdcopy="${d.id}">Copy</button></div><pre class="mts-nod"><code>${xe(d.ex.p)}</code></pre></div><p><b>You get:</b> ${xe(d.ex.get)}</p><p><b>Who stays in control:</b> ${xe(d.ex.ctl)}</p></details></article>`}
function body(glass){const pre=glass?'g':'s';
 return `<p class="wd-rule"><span aria-hidden="true">${ic('key')}</span><span><b>The rule of thumb:</b> ${xe(D.rule)}</span></p>
 ${picker(pre)}
 <div class="wd-doors">${D.doors.map(d=>card(d,glass)).join('')}</div>
 <section class="wd-shape glass"><h4>One program, four shapes of work</h4><p class="wd-sub">The same team, the same program. What changes is the shape of the work, and that decides the door.</p>
 <div class="wd-tbl" role="table" aria-label="One program, four shapes of work"><div class="wd-tr wd-th" role="row"><span role="columnheader"></span>${D.doors.map(d=>`<span role="columnheader" style="--dc:${d.col}">${xe(d.t)}</span>`).join('')}</div>
 ${[['The moment',d=>d.ex.m],['Who starts',d=>d.starts],['How long it runs',d=>d.runs],['What you get',d=>d.gets],['Who signs off',d=>d.sign]].map(([h,f])=>`<div class="wd-tr" role="row"><span role="rowheader"><b>${xe(h)}</b></span>${D.doors.map(d=>`<span role="cell">${xe(f(d))}</span>`).join('')}</div>`).join('')}</div></section>
 ${glass?`<section class="wd-guard"><h4>Guardrails that apply to all four</h4><div class="wd-gg">${D.guard.map(([i,h,p])=>`<div class="wd-g"><span aria-hidden="true">${ic(i)}</span><div><b>${xe(h)}</b><p>${xe(p)}</p></div></div>`).join('')}</div></section>`:''}
 <p class="wd-src"><b>Sources:</b> ${D.src.map(([n,u])=>`<a href="${xe(u)}" target="_blank" rel="noopener">${xe(n)}</a>`).join(' &middot; ')}. Availability and billing as at ${xe(D.asOf)}; features roll out gradually. Roles and programs in the examples are made up, and words in [square brackets] are yours to fill in.</p>`}
function pageDoors(){return `<header class="mts-h wd-h"><span class="mts-hi" aria-hidden="true">${ic('cater')}</span><div><div class="k">Which door?</div><h3>Chat, Cowork, Code or Autopilot</h3><p>&ldquo;${xe(D.quote)}&rdquo; Not in Copilot: each door opens onto a different shape of work. Here is how to pick the right one.</p></div></header>${body(false)}`}
PAGES['mts-doors']=pageDoors;
/* through the looking-glass: the same pack inside a playbook card, with the guardrails, billing and availability */
window.ccDoorsInto=el=>{if(el)el.innerHTML=body(true)};
document.addEventListener('click',e=>{const t=e.target;let b;
 if((b=t.closest('[data-wdans]'))){const box=b.closest('.wd-pick'),i=+b.dataset.q,q=D.qs[i],yes=b.dataset.wdans==='yes';
  box.querySelectorAll('.wd-q').forEach(li=>{const k=+li.dataset.q;li.classList.toggle('wd-wait',k>i+(yes?0:1));li.classList.toggle('wd-done',k<=i)});
  b.closest('.wd-yn').querySelectorAll('button').forEach(x=>x.classList.toggle('p',x===b));
  const id=yes?q.yes:(q.no||null),res=box.querySelector('.wd-res');
  if(id){res.innerHTML=result(id);box.querySelectorAll('.wd-q').forEach(li=>{if(+li.dataset.q>i)li.classList.add('wd-wait')})}else res.innerHTML='<p class="wd-hint">Next question.</p>';return}
 if((b=t.closest('[data-wdagain]'))){const box=b.closest('.wd-pick');box.querySelectorAll('.wd-q').forEach((li,k)=>{li.classList.toggle('wd-wait',k>0);li.classList.remove('wd-done')});box.querySelectorAll('.wd-yn .btn').forEach(x=>x.classList.remove('p'));box.querySelector('.wd-res').innerHTML='<p class="wd-hint">Your door appears here.</p>';return}
 if((b=t.closest('[data-wdshow]'))){const host=b.closest('.bk-host,.wd-host')||document,c=host.querySelector('#wd-'+b.dataset.wdshow);if(c){const dd=c.querySelector('details');if(dd)dd.open=true;c.scrollIntoView({behavior:'smooth',block:'center'});c.classList.add('wd-flash');setTimeout(()=>c.classList.remove('wd-flash'),1600)}return}
 if((b=t.closest('[data-wdcopy]'))){const d=door(b.dataset.wdcopy);if(d&&K.copyIt)K.copyIt(d.ex.p,()=>{b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1600)});return}});
})();

/* ===== v48 (13 October 2026): Advice from a Caterpillar, which Copilot fits what you are trying to do?
   Seven doors, up to three quick questions, then a likely path: Start here, You may need this, Watch for this and three
   questions to ask. Never "buy this": options, not recommendations. Every line carries a public source (sources), checked
   on the date in "as". A mayNeed line with "if" shows only for that answer. Re-check each source when you refresh an issue. */
